function levelOrder(root: TreeNode | null): number[][] {
  const result: number[][] = [];
  if (root === null) return result;

  // Очередь на массиве с указателем головы: shift() был бы O(n)
  const queue: TreeNode[] = [root];
  let head = 0;

  while (head < queue.length) {
    // Все узлы между head и концом очереди — ровно текущий уровень
    const levelSize = queue.length - head;
    const level: number[] = [];

    for (let i = 0; i < levelSize; i++) {
      const node = queue[head++];
      level.push(node.val);
      // Дети попадают в конец очереди — это уже следующий уровень
      if (node.left !== null) queue.push(node.left);
      if (node.right !== null) queue.push(node.right);
    }

    result.push(level);
  }

  return result;
}

// Время: O(n) — каждый узел попадает в очередь один раз
// Память: O(n) — очередь и ответ
